const assert = require('node:assert/strict')
const fs = require('node:fs')
const page = fs.readFileSync('app/visao-geral-projetos/page.tsx','utf8')
const api = fs.readFileSync('app/api/visao-geral-colunas/route.ts','utf8')
assert.match(page, /const podeEditarColunas=demo===true\|\|configuravel\|\|usuarioMaster/)
assert.match(page, /onClick=\{revelarAdicionarColuna\}/)
assert.match(page, /novaColunaRef\.current\?\.scrollIntoView\(\{behavior:'smooth',block:'nearest',inline:'end'\}\)/)
assert.match(page, /ref=\{novaColunaRef\} data-kanban-adicionar-coluna/)
assert.match(page, /ref=\{novoNomeRef\} value=\{novoNome\}/)
assert.match(page, /onClick=\{criar\} disabled=\{!novoNome\.trim\(\)\}/)
assert.match(page, /const id='manual_'\+Date\.now\(\)/)
assert.match(page, /setColunas\(a=>criarColunaGeral\(a,id,novoNome\)\)/)
assert.match(page, /onClick=\{\(\)=>void salvarConfig\(\)\}/)
assert.match(api, /if\(u\.role!=='master'\)return erro\('Somente o Master pode alterar as colunas\.',403\)/)
console.log('PASS: adição de coluna acessível no fim e por atalho mobile, criação, salvamento e RBAC Master')
